alter table public.profiles add column if not exists onboarded_at timestamptz;
create table if not exists public.recurring_bill_payments (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,recurring_bill_id uuid not null references public.recurring_bills(id) on delete cascade,due_month date not null,amount_minor bigint not null check(amount_minor>0),paid_at timestamptz not null default now(),unique(recurring_bill_id,due_month));
create table if not exists public.card_bill_payments (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,card_id uuid not null references public.credit_cards(id) on delete cascade,statement_month date not null,amount_minor bigint not null check(amount_minor>0),paid_on date not null,created_at timestamptz not null default now(),unique(card_id,statement_month));
alter table public.recurring_bill_payments enable row level security;alter table public.card_bill_payments enable row level security;
create policy recurring_bill_payments_own on public.recurring_bill_payments for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy card_bill_payments_own on public.card_bill_payments for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create index if not exists recurring_bill_payments_user_month_idx on public.recurring_bill_payments(user_id,due_month);create index if not exists card_bill_payments_user_month_idx on public.card_bill_payments(user_id,statement_month);
create or replace function public.validate_owned_relations() returns trigger language plpgsql security invoker set search_path='' as $$begin if tg_table_name='work_sessions' then if new.income_source_id is not null and not exists(select 1 from public.income_sources s where s.id=new.income_source_id and s.user_id=new.user_id) then raise exception 'invalid income source';end if;if new.vehicle_id is not null and not exists(select 1 from public.vehicles v where v.id=new.vehicle_id and v.user_id=new.user_id) then raise exception 'invalid vehicle';end if;elsif tg_table_name='transactions' then if new.income_source_id is not null and not exists(select 1 from public.income_sources s where s.id=new.income_source_id and s.user_id=new.user_id) then raise exception 'invalid income source';end if;elsif tg_table_name='card_purchases' then if not exists(select 1 from public.credit_cards c where c.id=new.card_id and c.user_id=new.user_id) then raise exception 'invalid card';end if;elsif tg_table_name='card_installments' then if not exists(select 1 from public.card_purchases p where p.id=new.purchase_id and p.user_id=new.user_id) then raise exception 'invalid purchase';end if;elsif tg_table_name='recurring_bill_payments' then if not exists(select 1 from public.recurring_bills b where b.id=new.recurring_bill_id and b.user_id=new.user_id) then raise exception 'invalid recurring bill';end if;elsif tg_table_name='card_bill_payments' then if not exists(select 1 from public.credit_cards c where c.id=new.card_id and c.user_id=new.user_id) then raise exception 'invalid card';end if;end if;return new;end;$$;
do $$ declare t text;begin foreach t in array array['work_sessions','transactions','card_purchases','card_installments','recurring_bill_payments','card_bill_payments'] loop execute format('drop trigger if exists validate_owned_relations on public.%I',t);execute format('create trigger validate_owned_relations before insert or update on public.%I for each row execute function public.validate_owned_relations()',t);end loop;end $$;
create or replace function public.create_card_purchase(p_card_id uuid,p_category_id text,p_description text,p_total_minor bigint,p_purchased_on date,p_installment_count integer,p_is_avoidable boolean default false) returns uuid language plpgsql security invoker set search_path='' as $$declare uid uuid:=auth.uid();purchase_id uuid;base_amount bigint;remainder bigint;i integer;amount_i bigint;first_month date;begin if uid is null then raise exception 'not authenticated';end if;if p_total_minor<=0 or p_installment_count<1 then raise exception 'invalid purchase';end if;if not exists(select 1 from public.credit_cards c where c.id=p_card_id and c.user_id=uid) then raise exception 'invalid card';end if;insert into public.card_purchases(user_id,card_id,category_id,description,total_minor,purchased_on,installment_count,is_avoidable) values(uid,p_card_id,p_category_id,nullif(trim(p_description),''),p_total_minor,p_purchased_on,p_installment_count,p_is_avoidable) returning id into purchase_id;base_amount:=p_total_minor/p_installment_count;remainder:=p_total_minor%p_installment_count;first_month:=date_trunc('month',p_purchased_on)::date;for i in 1..p_installment_count loop amount_i:=base_amount+case when i<=remainder then 1 else 0 end;insert into public.card_installments(user_id,purchase_id,installment_number,amount_minor,billing_month) values(uid,purchase_id,i,amount_i,(first_month+make_interval(months=>i-1))::date);end loop;return purchase_id;end;$$;
